#!/usr/bin/env python3
"""Grade a lab: resource contracts, bounded behavior checks and live.py.

Run with no argument to grade the whole lab, or with an outcome id to grade
one outcome. Each entry in requirements.json and each `if wants(...)` block
in live.py belongs to one outcome; an entry without an outcome is a guard
and runs for every outcome. config.yaml lists one validation script per
outcome (validation/validate-<id>.sh), each with its points. Like ATS020's
graders it prints one `PASS:` or `FAIL:` line.

Every run first checks that kubectl's current context is the lab's own:
ASTRONA_KUBE_CONTEXT when astrona sets it (an exam cluster sets its own),
otherwise the lab mode context in requirements.json. The node containers'
names and the container engine come from the environment astrona sets too,
so the same checks run on the lab's own cluster and on an exam cluster.

A qemu lab ("runtime": "qemu" in requirements.json) runs this file inside its
VM: the cluster is one kubeadm node named after the VM's host name (astrona
names the VM differently under `astrona test`), so NODE and WORKER are that
node and node_exec() runs the command on the VM with sudo.
"""
import json
import os
from pathlib import Path
import socket
import subprocess
import sys

DIRECTORY = Path(__file__).resolve().parent
REQUIREMENTS = json.loads((DIRECTORY / 'requirements.json').read_text())
CONTEXT = os.environ.get('ASTRONA_KUBE_CONTEXT') or REQUIREMENTS['context']
CLUSTER = os.environ.get('ASTRONA_KIND_CLUSTER') or REQUIREMENTS['cluster']
ENGINE = os.environ.get('ASTRONA_CONTAINER_ENGINE') or 'podman'
NAMESPACE = REQUIREMENTS['namespace']
QEMU = REQUIREMENTS.get('runtime') == 'qemu'
NODE = socket.gethostname() if QEMU else CLUSTER + '-control-plane'
WORKER = socket.gethostname() if QEMU else CLUSTER + '-worker'
SELECTED = sys.argv[1] if len(sys.argv) > 1 else None
MATCHED = set()


def wants(outcome):
    """True when this outcome is being graded (or the whole lab is)."""
    if SELECTED is None or SELECTED == outcome:
        MATCHED.add(outcome)
        return True
    return False


def selected(check):
    outcome = check.get('outcome')
    return outcome is None or wants(outcome)


def command(args, *, success=True):
    result = subprocess.run(args, capture_output=True, text=True, timeout=20)
    if success:
        assert result.returncode == 0, 'Required command failed: ' + args[0]
    return result


def kubectl(*args):
    return command(['kubectl', *args]).stdout.strip()


def node_exec(node, *args, success=True):
    """Run a command on a node (NODE or WORKER): in its container, or on the qemu VM."""
    prefix = ['sudo'] if QEMU else [ENGINE, 'exec', node]
    return command([*prefix, *args], success=success)


def get(kind, name, namespace=NAMESPACE):
    scope = ['-n', namespace] if namespace else []
    result = command(['kubectl', *scope, 'get', kind, name, '-o', 'json'], success=False)
    assert result.returncode == 0, f'Missing {kind} {name}' + (f' in namespace {namespace}' if namespace else '')
    return json.loads(result.stdout)


def contains(actual, expected):
    """Allow server-defaulted fields while preserving declared fields and lists."""
    if isinstance(expected, dict):
        return isinstance(actual, dict) and all(key in actual and contains(actual[key], value) for key, value in expected.items())
    if isinstance(expected, list):
        return isinstance(actual, list) and len(actual) == len(expected) and all(contains(left, right) for left, right in zip(actual, expected))
    return actual == expected


def resource_check(check):
    resource = get(check['kind'], check['name'], check.get('namespace', NAMESPACE))
    assert contains(resource, check['expected']), 'Required resource fields differ: ' + check['name']
    state = check.get('state')
    status = resource.get('status', {})
    if state == 'deployment':
        replicas = resource['spec'].get('replicas', 1)
        assert status.get('observedGeneration', 0) >= resource['metadata']['generation'], 'Current generation has not been observed'
        assert all(status.get(field, 0) == replicas for field in ('replicas', 'updatedReplicas', 'readyReplicas', 'availableReplicas')), 'Deployment rollout is incomplete'
    elif state == 'pod':
        assert status.get('phase') == 'Running' and any(condition['type'] == 'Ready' and condition['status'] == 'True' for condition in status.get('conditions', [])), 'Pod must be running and ready'
    elif state == 'job':
        assert status.get('succeeded', 0) == 1 and any(condition['type'] == 'Complete' and condition['status'] == 'True' for condition in status.get('conditions', [])), 'Job must complete successfully'
    elif state == 'pvc':
        assert status.get('phase') == 'Bound' and resource['spec'].get('volumeName'), 'Claim must bind to a volume'
    elif state == 'daemonset':
        desired = status.get('desiredNumberScheduled', 0)
        assert desired >= 2 and status.get('numberReady', 0) == desired and status.get('updatedNumberScheduled', 0) == desired, 'DaemonSet must cover both eligible nodes'
    return resource


def behavior_check(check):
    result = command(check['args'], success=not check.get('denied', False))
    if check.get('denied'):
        assert result.returncode == 1, 'Expected a bounded denied request, not a successful request or execution error'
        output = result.stdout + result.stderr
        assert any(marker in output.lower() for marker in check['failure_markers']), 'Request did not fail for the required reason'
    output = result.stdout.strip()
    if 'equals' in check:
        assert output == check['equals'], 'Command returned an unexpected value'
    for marker in check.get('contains', []):
        assert marker in output, 'Command did not return the expected application evidence'
    if 'json' in check:
        assert contains(json.loads(output), check['json']), 'Command returned an unexpected JSON contract'
    return result


def main():
    if kubectl('config', 'current-context') != CONTEXT:
        sys.exit('Refusing to operate on another Kubernetes context')
    for check in REQUIREMENTS.get('resources', []):
        if selected(check):
            resource_check(check)
    for check in REQUIREMENTS.get('behavior', []):
        if selected(check):
            behavior_check(check)
    extra = DIRECTORY / 'live.py'
    if extra.exists():
        exec(compile(extra.read_text(), str(extra), 'exec'), globals())
    assert SELECTED is None or SELECTED in MATCHED, 'Unknown outcome: ' + SELECTED
    print('PASS: ' + (SELECTED or 'every outcome'))


if __name__ == '__main__':
    try:
        main()
    except (AssertionError, KeyError, ValueError, subprocess.SubprocessError) as error:
        print('FAIL: ' + str(error))
        sys.exit(1)
ASTRONA_LAB_FILE
write_file 0644 testing/live.py <<'ASTRONA_LAB_FILE'
# Checks that read the running processes and files of this lab's node
# containers. check.py runs this file with NODE, WORKER, node_exec(),
# kubectl(), get() and wants() already defined.
import re
import time


def process_arguments(container, program):
    """Return the command line of the newest running process with this name."""
    found = node_exec(container, 'pgrep', '-n', '-f', '^(/[^ ]*/)?' + program + '( |$)', success=False).stdout.strip()
    assert found, program + ' is not running on ' + container
    raw = node_exec(container, 'cat', '/proc/' + found + '/cmdline', success=False).stdout
    arguments = [item for item in raw.split('\0') if item]
    assert arguments, program + ' stopped while it was read; try again'
    return arguments


def flag_value(arguments, name):
    """The value a single-value flag takes: the last occurrence wins."""
    value = None
    for item in arguments:
        if item.startswith('--' + name + '='):
            value = item.split('=', 1)[1]
        elif item == '--' + name:
            value = 'true'
    return value


def flag_list(arguments, name):
    """The items of a list flag: every occurrence adds its items."""
    items = []
    for item in arguments:
        if item.startswith('--' + name + '='):
            items += [part.strip() for part in item.split('=', 1)[1].split(',') if part.strip()]
    return items


def file_mode(container, path):
    result = node_exec(container, 'stat', '-c', '%a %U:%G', path, success=False)
    assert result.returncode == 0, path + ' is missing on ' + container
    mode, owner = result.stdout.split()
    return int(mode, 8), owner


def assert_mode_at_most(container, path, limit, owner='root:root'):
    mode, actual_owner = file_mode(container, path)
    assert mode & ~limit == 0, '%s has mode %o; it must be %o or stricter' % (path, mode, limit)
    if owner:
        assert actual_owner == owner, path + ' must be owned by ' + owner


def configz(node):
    return json.loads(kubectl('get', '--raw', '/api/v1/nodes/' + node + '/proxy/configz'))['kubeletconfig']


def assert_api_ready():
    assert kubectl('--request-timeout=5s', 'get', '--raw=/readyz') == 'ok', 'The API server must stay ready'


def assert_node_ready(node):
    status = get('node', node, namespace=None)['status']
    assert any(item['type'] == 'Ready' and item['status'] == 'True' for item in status['conditions']), node + ' must stay Ready'


KUBE_BENCH_IMAGE = 'docker.io/aquasec/kube-bench:v0.10.6'
HOST_PATHS = [('var-lib-etcd', '/var/lib/etcd', '/var/lib/etcd'), ('var-lib-kubelet', '/var/lib/kubelet', '/var/lib/kubelet'),
              ('etc-systemd', '/etc/systemd', '/etc/systemd'), ('etc-kubernetes', '/etc/kubernetes', '/etc/kubernetes'),
              ('usr-bin', '/usr/bin', '/usr/local/mount-from-host/bin')]


def run_with_limit(arguments, limit, text_input=None):
    return subprocess.run(arguments, capture_output=True, text=True, timeout=limit, input=text_input)


def finished_log(kind, name, condition):
    waited = run_with_limit(['kubectl', '-n', NAMESPACE, 'wait', condition, kind + '/' + name, '--timeout=150s'], 170)
    assert waited.returncode == 0, 'The grader ' + kind + ' ' + name + ' did not finish'
    return run_with_limit(['kubectl', '-n', NAMESPACE, 'logs', kind + '/' + name], 30).stdout


def image_output(name, script):
    """Run a shell script in a short pod with the kube-bench image."""
    run_with_limit(['kubectl', '-n', NAMESPACE, 'delete', 'pod', name, '--ignore-not-found', '--wait=true'], 60)
    started = run_with_limit(['kubectl', '-n', NAMESPACE, 'run', name, '--restart=Never', '--image-pull-policy=IfNotPresent',
                              '--image=' + KUBE_BENCH_IMAGE, '--command', '--', 'sh', '-c', script], 30)
    assert started.returncode == 0, 'Could not start the grader pod'
    try:
        return finished_log('pod', name, "--for=jsonpath={.status.phase}=Succeeded")
    finally:
        run_with_limit(['kubectl', '-n', NAMESPACE, 'delete', 'pod', name, '--ignore-not-found', '--wait=false'], 30)


def bench_job(name, arguments):
    """Run kube-bench as a Job on the control plane node and return its log."""
    container = {'name': 'kube-bench', 'image': KUBE_BENCH_IMAGE, 'imagePullPolicy': 'IfNotPresent',
                 'command': ['kube-bench', 'run'] + arguments,
                 'volumeMounts': [{'name': item[0], 'mountPath': item[2], 'readOnly': True} for item in HOST_PATHS]}
    spec = {'hostPID': True, 'restartPolicy': 'Never', 'containers': [container],
            'nodeSelector': {'node-role.kubernetes.io/control-plane': ''},
            'tolerations': [{'key': 'node-role.kubernetes.io/control-plane', 'operator': 'Exists', 'effect': 'NoSchedule'}],
            'volumes': [{'name': item[0], 'hostPath': {'path': item[1]}} for item in HOST_PATHS]}
    job = {'apiVersion': 'batch/v1', 'kind': 'Job', 'metadata': {'name': name, 'namespace': NAMESPACE},
           'spec': {'backoffLimit': 0, 'template': {'spec': spec}}}
    run_with_limit(['kubectl', '-n', NAMESPACE, 'delete', 'job', name, '--ignore-not-found', '--wait=true'], 60)
    applied = run_with_limit(['kubectl', 'apply', '-f', '-'], 30, json.dumps(job))
    assert applied.returncode == 0, 'Could not start the grader Job'
    try:
        return finished_log('job', name, '--for=condition=complete')
    finally:
        run_with_limit(['kubectl', '-n', NAMESPACE, 'delete', 'job', name, '--ignore-not-found', '--wait=false'], 30)


def learner_job(name):
    """Return the Job, its pod and its log after checking that it completed."""
    job = get('job', name)
    assert job.get('status', {}).get('succeeded', 0) >= 1, 'The Job ' + name + ' has not completed'
    pods = json.loads(kubectl('-n', NAMESPACE, 'get', 'pods', '-l', 'job-name=' + name, '-o', 'json'))['items']
    finished = [pod for pod in pods if pod['status'].get('phase') == 'Succeeded']
    assert finished, 'The Job ' + name + ' has no finished pod'
    log = run_with_limit(['kubectl', '-n', NAMESPACE, 'logs', 'pod/' + finished[0]['metadata']['name']], 30).stdout
    return job, finished[0], log


def command_line(pod_spec):
    container = pod_spec['containers'][0]
    return container.get('command', []) + container.get('args', [])


def option(arguments, name):
    """The value of an option given as --name value or --name=value."""
    value = None
    for index, item in enumerate(arguments):
        if item == '--' + name and index + 1 < len(arguments):
            value = arguments[index + 1]
        elif item.startswith('--' + name + '='):
            value = item.split('=', 1)[1]
    return value

job, pod, log = learner_job('master-audit')
assert option(command_line(pod['spec']), 'targets') == 'master', 'Run kube-bench with --targets master'
saved = get('configmap', 'master-result').get('data', {})
if wants('totals-match'):
    totals = {}
    for number, state in re.findall(r'^(\d+) checks (PASS|FAIL|WARN|INFO)$', log, re.M):
        totals[state.lower()] = number
    assert len(totals) == 4, 'The log of master-audit has no summary'
    for key, number in totals.items():
        assert saved.get(key, '').strip() == number, 'The key ' + key + ' differs from the summary of the report'
if wants('section-counts-match'):
    for section in ('1.1', '1.2'):
        expected = len(re.findall(r'^\[FAIL\] ' + re.escape(section) + r'\.\d+', log, re.M))
        assert saved.get('fail-' + section, '').strip() == str(expected), 'The key fail-' + section + ' differs from the report'
ASTRONA_LAB_FILE
